const staticData = $getWorkflowStaticData('global');
const now = new Date().toISOString();
const caseId = 'CASE-' + Date.now() + '-' + Math.floor(Math.random()*10000);
const incidentId = 'INC-' + Date.now();

if (!staticData.executionHistory) staticData.executionHistory = [];
if (!staticData.cases) staticData.cases = {};

staticData.cases[caseId] = {
  case_id: caseId, incident_id: incidentId, created_at: now,
  entities: [], threat_score: 0, memory: [], reports: {}
};
staticData.executionHistory.push({ case_id: caseId, started_at: now, execution_id: $execution.id });

const input = $json.body || $json;

return [{ json: {
  case_id: caseId, incident_id: incidentId, timestamp: now,
  execution_id: $execution.id, raw_input: input
}}];

const raw = $json.raw_input;
const text = JSON.stringify(raw).toLowerCase();
let type = 'unknown';
const cveRegex = /cve-\d{4}-\d{4,7}/;
const ipRegex = /\b(?:\d{1,3}\.){3}\d{1,3}\b/;
const hashRegex = /\b[a-f0-9]{32,64}\b/;
const urlRegex = /https?:\/\//;

if (cveRegex.test(text)) type = 'cve';
else if (raw && (raw.dockerfile || raw.terraform || raw.kubernetes_yaml || raw.source_code || raw.ci_cd_yaml || raw.language)) type = 'code';
else if (raw && (raw.firewall_log || raw.windows_event_log || raw.linux_log || raw.syslog || raw.edr_alert || raw.siem_alert)) type = 'logs';
else if (hashRegex.test(text) || ipRegex.test(text) || urlRegex.test(text) || (raw && raw.ioc)) type = 'ioc';
else if (raw && (raw.pdf_report || raw.text_report)) type = 'report';
else type = 'logs';

return [{ json: { ...$json, input_type: type } }];

const text = JSON.stringify($json.raw_input);
const ips = [...new Set((text.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) || []))];
const domains = [...new Set((text.match(/\b(?:[a-z0-9-]+\.)+[a-z]{2,}\b/gi) || []))];
const hashes = [...new Set((text.match(/\b[a-f0-9]{32}\b|\b[a-f0-9]{40}\b|\b[a-f0-9]{64}\b/gi) || []))];
const urls = [...new Set((text.match(/https?:\/\/[^\s"']+/g) || []))];
return [{ json: { ...$json, entities: { ips, domains, hashes, urls } } }];

const items = $input.all();
const vt = items[0]?.json || {};
const abuse = items[1]?.json || {};
const otx = items[2]?.json || {};
const geo = items[3]?.json || {};

let score = 0;
const vtMalicious = vt?.data?.attributes?.last_analysis_stats?.malicious || 0;
score += Math.min(vtMalicious * 5, 40);
const abuseScore = abuse?.data?.abuseConfidenceScore || 0;
score += Math.min(abuseScore * 0.4, 40);
const otxPulses = (otx?.pulse_info?.count) || 0;
score += Math.min(otxPulses * 2, 20);

score = Math.min(Math.round(score), 100);
let severity = 'informational';
if (score >= 80) severity = 'critical';
else if (score >= 60) severity = 'high';
else if (score >= 30) severity = 'medium';
else if (score > 0) severity = 'low';

const original = $('A1: Extract Entities & IOCs').first().json;
return [{ json: { ...original, threat_intel: { virustotal: vt, abuseipdb: abuse, otx: otx, geoip: geo }, confidence: score, severity } }];

const query = $json.query || {};
const approved = query.approved === 'true';
const explicitlyRejected = query.approved === 'false';

const priorContext = $('A2: Require Human Approval').item.json;

return [{ json: {
  case_id: priorContext.case_id,
  dossier: priorContext.dossier,
  playbook: priorContext.playbook,
  approved,
  status: approved ? 'approved' : (explicitlyRejected ? 'rejected' : 'timed_out_not_approved')
}}];

const raw = $json.raw_input;
const code = raw.source_code || raw.dockerfile || raw.terraform || raw.kubernetes_yaml || raw.ci_cd_yaml || '';
let language = 'unknown';
if (raw.dockerfile) language = 'dockerfile';
else if (raw.terraform) language = 'terraform';
else if (raw.kubernetes_yaml) language = 'kubernetes';
else if (raw.ci_cd_yaml) language = 'ci_cd';
else if (/def |import /.test(code)) language = 'python';
else if (/function |const |=>/.test(code)) language = 'javascript';

const secretPatterns = [
  /aws_secret_access_key\s*=\s*['"][A-Za-z0-9\/+=]{20,}/i,
  /api[_-]?key\s*[:=]\s*['"][A-Za-z0-9]{16,}/i,
  /-----BEGIN (RSA|EC|DSA|OPENSSH)? ?PRIVATE KEY-----/,
  /ghp_[A-Za-z0-9]{36}/,
  /AKIA[0-9A-Z]{16}/
];
const secretsFound = secretPatterns.filter(p => p.test(code)).length;
return [{ json: { ...$json, language, code, secrets_detected: secretsFound } }];

