const text = JSON.stringify($json.raw_input);
const cve = (text.match(/CVE-\d{4}-\d{4,7}/i) || [null])[0];
const hash = (text.match(/\b[a-f0-9]{64}\b|\b[a-f0-9]{40}\b|\b[a-f0-9]{32}\b/i) || [null])[0];
const url = (text.match(/https?:\/\/[^\s"']+/) || [null])[0];
return [{ json: { ...$json, cve, hash, url } }];

function safe(nodeName, path) {
  try {
    const item = $(nodeName).item.json;
    return path ? (item[path] ?? null) : item;
  } catch (e) {
    return null;
  }
}

const case_id = safe('Init Shared Context', 'case_id') || $json.case_id || null;

const bundle = {
  case_id: case_id,
  dossier: safe('A1: Format Dossier', 'dossier'),
  playbook: safe('A2: Evaluate Approval', 'playbook') || safe('A2: Require Human Approval', 'playbook'),
  approval_status: safe('A2: Evaluate Approval', 'status'),
  audit_report: safe('A4: Format Compliance', 'audit_report') || safe('A3: Format Audit Report', 'audit_report'),
  compliance_report: safe('A4: Format Compliance', 'compliance_report'),
  threat_intel_report: safe('A5: Format TI Output', 'threat_intel_report')
};

return [{ json: bundle }];

parameters.text:
=You are an executive cybersecurity advisor. Create a comprehensive executive briefing for case {{ $json.case_id }}.

CONTEXT:
- Threat Intel Report: {{ JSON.stringify($json.threat_intel_report) }}
- Dossier: {{ $json.dossier ? JSON.stringify($json.dossier) : "Not applicable for this run" }}
- Audit Report: {{ $json.audit_report ? JSON.stringify($json.audit_report) : "Not applicable for this run" }}
- Compliance Report: {{ $json.compliance_report ? JSON.stringify($json.compliance_report) : "Not applicable for this run" }}
- Playbook: {{ $json.playbook ? JSON.stringify($json.playbook) : "Not applicable for this run" }}
- Approval Status: {{ $json.approval_status || "Pending" }}

Produce the following executive deliverables in STRICT JSON format. Do NOT output markdown, explanations, or any text outside the JSON structure.

{
  "CEO_report": "2-3 paragraph executive summary for CEO focusing on business risk and strategic implications",
  "Board_report": "Formal board briefing covering governance, compliance, and strategic risk posture",
  "Technical_report": "Concise technical summary for CISO/CTO with specific remediation timeline",
  "Risk_summary": "Bullet-point risk assessment with likelihood/impact matrix",
  "Business_impact": "Analysis of potential financial, operational, and reputational impacts",
  "Executive_recommendations": "Numbered list of top 3-5 strategic recommendations with priority and estimated effort"
}

parameters.jsCode:
const bundle = $('Assemble Case Bundle').item.json;
const execOutput = $json;  // Output parser provides structured $json directly

const staticData = $getWorkflowStaticData('global');
const caseId = bundle.case_id;
const started = staticData.cases && staticData.cases[caseId] ? staticData.cases[caseId].created_at : new Date().toISOString();
const latencyMs = new Date() - new Date(started);

const finalCase = {
  case_id: caseId,
  workflow: 'cyber_multiagent_platform',
  timestamp: new Date().toISOString(),
  severity: (bundle.dossier && bundle.dossier.severity) || (bundle.audit_report && bundle.audit_report.severity) || (bundle.threat_intel_report && bundle.threat_intel_report.severity) || 'informational',
  confidence: (bundle.dossier && bundle.dossier.confidence) || (bundle.threat_intel_report && bundle.threat_intel_report.confidence) || 0,
  findings: [].concat(
    (bundle.dossier && bundle.dossier.findings) || [],
    (bundle.audit_report && bundle.audit_report.findings) || [],
    (bundle.threat_intel_report && bundle.threat_intel_report.findings) || []
  ),
  recommendations: execOutput.Executive_recommendations || [],
  references: [],
  evidence_json: JSON.stringify({
    dossier: bundle.dossier,
    audit_report: bundle.audit_report,
    compliance_report: bundle.compliance_report,
    threat_intel_report: bundle.threat_intel_report,
    playbook: bundle.playbook,
    approval_status: bundle.approval_status,
    executive_report: execOutput  // Include full executive report
  }),
  ai_summary: execOutput.ai_summary || execOutput.CEO_report || '',
  execution_id: $execution.id,
  latency_ms: latencyMs
};

if (staticData.cases && staticData.cases[caseId]) {
  staticData.cases[caseId].reports.final = finalCase;
}

return [{ json: finalCase }];

return [{ json: {
  execution_id: $execution.id,
  workflow: $workflow.name,
  failed_node: $json.execution ? $json.execution.lastNodeExecuted : ($json.node ? $json.node.name : 'unknown'),
  error_message: $json.execution ? $json.execution.error?.message : ($json.error ? $json.error.message : JSON.stringify($json)),
  timestamp: new Date().toISOString()
}}];
